mapper.select:
SELECT id, admin_id AS adminId, operation_type AS operationType, module, operation_desc AS operationDesc, request_url AS requestUrl, request_method AS requestMethod, request_params AS requestParams, ip, user_agent AS userAgent, cost_time AS costTime, create_time AS createTime FROM operation_log
AND admin_id = #{adminId}
AND module = #{module}
AND operation_type = #{operationType}
AND operation_desc LIKE CONCAT('%', #{operationDescLike}, '%')
AND create_time >= #{createTimeStart}
AND create_time <= #{createTimeEnd}
ORDER BY create_time DESC LIMIT #{offset}, #{size}
